from taf.gnb.oam.coam.vdu.utilities.http_client import HttpClient
from taf.gnb.oam.coam.vdu.utilities.multipart_encoder import MultipartEncoder


class SWMv1HttpClient(HttpClient):
    """ This class provides a client for the SWM v1 API. """
    def __init__(self, base_url, connection_alias):
        super(SWMv1HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/swm/v1"

    def trigger_sw_update(self, sw_update_type, sw_update_source, target_bd_file_path, target_bd_file_name, timeout=30):
        endpoint = "/operations/sw-update"

        with open(target_bd_file_path, "rb") as file:
            multipart_data = MultipartEncoder(
                fields={
                    "targetBdFile": (target_bd_file_name, file, "text/xml"),
                    "swUpdateSource": sw_update_source,
                    "swUpdateType": sw_update_type
                }
            )

            headers = {
                "Content-Type": multipart_data.content_type,
            }

            return self._send_post_request(endpoint=endpoint,
                                           data=multipart_data.to_bytes(),
                                           timeout=timeout,
                                           headers=headers)

    def get_sw_update_operation_status(self, operation_id, timeout=30):
        endpoint = f"/operations/sw-update/{operation_id}"
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, timeout=timeout, headers=headers)

    def get_sw_update_file_list(self, operation_id, timeout=30):
        endpoint = f"/operations/sw-update-file-list/{operation_id}"
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, timeout=timeout, headers=headers)

    def post_sw_update_file(self, operation_id, file_name, file_path, total_files, file_number, timeout=30):
        endpoint = f"/operations/sw-update-file/{operation_id}"

        with open(file_path, "rb") as file:
            multipart_data = MultipartEncoder(
                fields={
                    "file": (file_name, file, "text/xml"),
                    "fileName": file_name,
                    "totalFiles": total_files,
                    "fileNumber": file_number
                }
            )

            headers = {
                "Content-Type": multipart_data.content_type,
            }

            return self._send_post_request(endpoint=endpoint,
                                           data=multipart_data.to_bytes(),
                                           timeout=timeout,
                                           headers=headers)

    def delete_sw_update_operation(self, operation_id, timeout=30):
        endpoint = f"/operations/sw-update/{operation_id}"
        self._send_delete_request(endpoint=endpoint, timeout=timeout)

    def delete_sw_update_file_operation(self, operation_id, timeout=30):
        endpoint = f"/operations/sw-update-file/{operation_id}"
        self._send_delete_request(endpoint=endpoint, timeout=timeout)
